//! Icon assets embedded in the binary.
use gpui::*;

pub struct Assets;
// `icon_bytes`, generated by build.rs from the files in `assets/`: Tabler
// outline icons as the Electron app uses them (see `assets/LICENSE-tabler`),
// and Picto's own glyphs transcribed from `src/shared/ui/icons`.
include!(concat!(env!("OUT_DIR"), "/icons.rs"));

impl AssetSource for Assets {
    fn load(&self, path: &str) -> anyhow::Result<Option<std::borrow::Cow<'static, [u8]>>> {
        Ok(icon_bytes(path).map(std::borrow::Cow::Borrowed))
    }
    fn list(&self, _: &str) -> anyhow::Result<Vec<SharedString>> {
        Ok(vec![])
    }
}
